const express = require('express');
const crypto = require('crypto');
const app = express();

// Configuration
const JWT_SECRET = crypto.randomBytes(32);
const USERS_DB = new Map();
const SESSIONS = new Map();

// Utility: Base64URL encode
function base64urlEncode(buf) {
  return buf.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

// Utility: Base64URL decode
function base64urlDecode(str) {
  // Restore standard base64 characters
  str = str.replace(/-/g, '+').replace(/_/g, '/');
  // Add padding
  while (str.length % 4) str += '=';
  return Buffer.from(str, 'base64');
}

// JWT creation
function createJWT(payload) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const headerB64 = base64urlEncode(Buffer.from(JSON.stringify(header)));
  const payloadB64 = base64urlEncode(Buffer.from(JSON.stringify(payload)));
  const signingInput = `${headerB64}.${payloadB64}`;
  const signature = crypto.createHmac('sha256', JWT_SECRET)
    .update(signingInput)
    .digest();
  const signatureB64 = base64urlEncode(signature);
  return `${signingInput}.${signatureB64}`;
}

// JWT verification - validates structure and signature
function verifyJWT(token) {
  if (!token || typeof token !== 'string') return null;

  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const [headerB64, payloadB64, signatureB64] = parts;

  // Decode and validate header
  let header;
  try {
    header = JSON.parse(base64urlDecode(headerB64).toString());
  } catch (e) {
    return null;
  }

  // Algorithm validation - only allow HS256
  if (header.alg !== 'HS256') return null;
  if (header.typ !== 'JWT') return null;

  // Recompute signature
  const signingInput = `${headerB64}.${payloadB64}`;
  const expectedSig = crypto.createHmac('sha256', JWT_SECRET)
    .update(signingInput)
    .digest();

  // Decode provided signature
  const providedSig = base64urlDecode(signatureB64);

  // Constant-time comparison
  if (providedSig.length !== expectedSig.length) return null;
  if (!crypto.timingSafeEqual(providedSig, expectedSig)) return null;

  // Decode payload
  let payload;
  try {
    payload = JSON.parse(base64urlDecode(payloadB64).toString());
  } catch (e) {
    return null;
  }

  // Check expiration
  if (payload.exp && Date.now() > payload.exp * 1000) return null;

  return payload;
}

app.use(express.json());

// Registration endpoint
app.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });
  if (USERS_DB.has(username)) return res.status(409).json({ error: 'User exists' });

  const salt = crypto.randomBytes(16);
  const hash = crypto.scryptSync(password, salt, 64);
  USERS_DB.set(username, { hash, salt, role: 'user' });
  res.json({ success: true });
});

// Login endpoint
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });

  const user = USERS_DB.get(username);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const hash = crypto.scryptSync(password, user.salt, 64);
  if (!crypto.timingSafeEqual(hash, user.hash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = createJWT({
    sub: username,
    role: user.role,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + 3600
  });

  res.json({ token });
});

// Auth middleware
function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }

  const token = authHeader.slice(7);
  const payload = verifyJWT(token);
  if (!payload) return res.status(401).json({ error: 'Invalid token' });

  req.user = payload;
  next();
}

// Role check middleware
function requireRole(role) {
  return (req, res, next) => {
    if (req.user.role !== role) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Protected endpoint
app.get('/profile', authMiddleware, (req, res) => {
  res.json({ user: req.user });
});

// Admin endpoint
app.get('/admin/users', authMiddleware, requireRole('admin'), (req, res) => {
  const users = [];
  USERS_DB.forEach((v, k) => users.push({ username: k, role: v.role }));
  res.json({ users });
});

// Admin action: promote user
app.post('/admin/promote', authMiddleware, requireRole('admin'), (req, res) => {
  const { username } = req.body;
  const user = USERS_DB.get(username);
  if (!user) return res.status(404).json({ error: 'User not found' });
  user.role = 'admin';
  res.json({ success: true });
});

// Token refresh with role re-evaluation
app.post('/refresh', authMiddleware, (req, res) => {
  const currentUser = USERS_DB.get(req.user.sub);
  // Issue new token with current role from DB
  const newPayload = {
    sub: req.user.sub,
    role: currentUser ? currentUser.role : req.user.role,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + 3600
  };
  const token = createJWT(newPayload);
  res.json({ token });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

module.exports = app;
